      calm: 0,
      friendly: 0,
      bold: 0,
      clever: 0,
      adventurous: 0,
      determined: 0
    };

    const questionEl = document.getElementById("question");
    const answersEl = document.getElementById("answers");
    const progressEl = document.getElementById("progress");
    const quizEl = document.getElementById("quiz");
    const resultEl = document.getElementById("result");
    const pokemonImageEl = document.getElementById("pokemonImage");
    const pokemonNameEl = document.getElementById("pokemonName");
    const pokemonDescriptionEl = document.getElementById("pokemonDescription");

    function showQuestion() {
      const question = questions[currentQuestionIndex];

      progressEl.textContent = `Question ${currentQuestionIndex + 1} of ${questions.length}`;
      questionEl.textContent = question.text;
      answersEl.innerHTML = "";

      question.answers.forEach(answer => {
        const button = document.createElement("button");
        button.textContent = answer.text;
        button.addEventListener("click", () => chooseAnswer(answer.type));
        answersEl.appendChild(button);
      });
    }

    function chooseAnswer(type) {
      scores[type]++;

      currentQuestionIndex++;

      if (currentQuestionIndex < questions.length) {
        showQuestion();
      } else {
        showResult();
      }
    }

    function showResult() {
      const topType = Object.keys(scores).reduce((bestType, currentType) => {
        return scores[currentType] > scores[bestType] ? currentType : bestType;
      });

      const result = pokemonResults[topType];

      pokemonNameEl.textContent = result.name;
      pokemonDescriptionEl.textContent = result.description;
      pokemonImageEl.src = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/showdown/${getPokemonId(result.name)}.gif`;
      pokemonImageEl.onerror = () => {
        pokemonImageEl.src = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${getPokemonId(result.name)}.png`;
      };

      quizEl.hidden = true;
      resultEl.hidden = false;
    }

    function getPokemonId(name) {
      const ids = {
        pikachu: 25,
        squirtle: 7,
        bulbasaur: 1,
        charmander: 4,
        eevee: 133,
        mew: 151,
        lucario: 448
      };

      return ids[name];
    }

    function restartQuiz() {
      currentQuestionIndex = 0;

      Object.keys(scores).forEach(type => {
        scores[type] = 0;
      });

      resultEl.hidden = true;
      quizEl.hidden = false;

      showQuestion();
    }

    showQuestion();
  </script>
</body>
</html>
